const verses=[
{ref:'John 3:16',text:'For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life.'},
{ref:'Psalm 119:11',text:'Thy word have I hid in mine heart, that I might not sin against thee.'},
{ref:'Philippians 4:13',text:'I can do all things through Christ which strengtheneth me.'},
{ref:'Proverbs 3:5',text:'Trust in the LORD with all thine heart; and lean not unto thine own understanding.'},
{ref:'Matthew 5:16',text:'Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.'},
{ref:'Romans 8:28',text:'And we know that all things work together for good to them that love God, to them who are the called according to his purpose.'},
{ref:'Isaiah 41:10',text:'Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.'}
];
const key='himh-progress-v1';let progress=JSON.parse(localStorage.getItem(key)||'{}');let mode='build';let answer=[];let chosenMissing='';
const $=id=>document.getElementById(id),esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=()=>verses[Number($('verseSelect').value)||0];
function save(ok){progress.best=Math.max(progress.best||0,ok?10:0);const today=new Date().toISOString().slice(0,10);if(ok){if(progress.last!==today){const y=new Date(Date.now()-86400000).toISOString().slice(0,10);progress.streak=(progress.last===y?(progress.streak||0)+1:1);progress.last=today}progress.learned=progress.learned||{};progress.learned[current().ref]=true}localStorage.setItem(key,JSON.stringify(progress));stats()}
function stats(){$('best').textContent=progress.best||0;$('streak').textContent=progress.streak||0;$('learned').textContent=Object.keys(progress.learned||{}).length}
function render(){const v=current();$('feedback').textContent='';if(mode==='build'){answer=[];const words=v.text.replace(/[.,;:!?]/g,'').split(/\s+/);const shuffled=[...words].sort(()=>Math.random()-.5);$('game').innerHTML='<h2>Build the verse</h2><p class="prompt">Tap the words in order. Tap a chosen word to return it.</p><div class="answer-line" id="answer"></div><div class="tile-bank" id="bank">'+shuffled.map((w,i)=>'<button class="tile" data-i="'+i+'">'+esc(w)+'</button>').join('')+'</div><button class="check" id="check">Check verse</button>';document.querySelectorAll('#bank button').forEach(b=>b.onclick=()=>{answer.push({i:Number(b.dataset.i),w:b.textContent});b.disabled=true;drawAnswer()});$('check').onclick=()=>{const expected=v.text.replace(/[.,;:!?]/g,'').split(/\s+/).join(' ').toLowerCase();const actual=answer.map(x=>x.w).join(' ').toLowerCase();const ok=expected===actual;$('feedback').textContent=ok?'Correct — you built '+v.ref+'.':'Not quite yet. Try again; the words stay here.';if(ok){save(true);setTimeout(next,900)}};}else if(mode==='missing'){const words=v.text.split(/\s+/);const candidates=words.map((w,i)=>({w:w.replace(/[.,;:!?]/g,''),i})).filter(x=>x.w.length>4);const pick=candidates[Math.floor(candidates.length/2)]||candidates[0];chosenMissing=pick.w;const masked=words.slice();masked[pick.i]='_____';const options=[pick.w,...verses.filter(x=>x.ref!==v.ref).map(x=>x.text.split(/\s+/).filter(w=>w.length>4)[2]).filter(Boolean).slice(0,3)].sort(()=>Math.random()-.5);$('game').innerHTML='<h2>Find the missing word</h2><p class="prompt">'+esc(v.ref)+' · choose the word that completes the verse.</p><p class="verse-text">'+esc(masked.join(' '))+'</p><div class="choices">'+options.map(w=>'<button class="choice" data-word="'+esc(w)+'">'+esc(w)+'</button>').join('')+'</div>';document.querySelectorAll('.choice').forEach(b=>b.onclick=()=>{const ok=b.dataset.word.toLowerCase()===chosenMissing.toLowerCase();$('feedback').textContent=ok?'Yes — that is the missing word.':'Not that word. Read the verse and try again.';if(ok){save(true);setTimeout(next,900)}})}else{const distractors=verses.filter(x=>x.ref!==v.ref).sort(()=>Math.random()-.5).slice(0,3);const all=[v,...distractors].sort(()=>Math.random()-.5);$('game').innerHTML='<h2>Match the reference</h2><p class="prompt">Read the verse, then choose its reference.</p><p class="verse-text">'+esc(v.text)+'</p><div class="references">'+all.map(x=>'<button class="ref-option" data-ref="'+esc(x.ref)+'">'+esc(x.ref)+'</button>').join('')+'</div>';document.querySelectorAll('.ref-option').forEach(b=>b.onclick=()=>{const ok=b.dataset.ref===v.ref;$('feedback').textContent=ok?'Right — '+v.ref+'.':'Try another reference.';if(ok){save(true);setTimeout(next,900)}})}}
function drawAnswer(){$('answer').innerHTML=answer.map((x,i)=>'<button class="answer-tile" data-a="'+i+'">'+esc(x.w)+' ×</button>').join('');document.querySelectorAll('.answer-tile').forEach(b=>b.onclick=()=>{const x=answer.splice(Number(b.dataset.a),1)[0];const orig=[...document.querySelectorAll('#bank .tile')].find(t=>Number(t.dataset.i)===x.i);if(orig)orig.disabled=false;drawAnswer()})}
function next(){$('verseSelect').value=String((Number($('verseSelect').value)+1)%verses.length);render()}
$('verseSelect').innerHTML=verses.map((v,i)=>'<option value="'+i+'">'+esc(v.ref)+'</option>').join('');$('verseSelect').onchange=render;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));render()});$('deck').innerHTML=verses.map(v=>'<article class="verse-card"><strong>'+esc(v.ref)+'</strong><p>'+esc(v.text)+'</p></article>').join('');stats();render();
